typedef unsigned char u_char;
typedef unsigned int u_int;
typedef unsigned long long u_long;

struct nglTexture;

struct nglQuadVertex
{
  float X, Y;
  float U, V;
  u_int Color;
};

struct nglQuad
{
  nglQuadVertex Verts[4];
  float Z;
  u_int MapFlags;
  u_int BlendMode;
  u_int BlendModeConstant;
  nglTexture* Tex;
};

struct nglScene
{
  char _pad[1096];
  bool ZTestEnable;
};

enum nglGSRegType
{
  NGL_GS_FOG,
  NGL_GS_PRMODE,
  NGL_GS_TEX0_1,
  NGL_GS_TEX1_1,
  NGL_GS_TEXCLUT,
  NGL_GS_MIPTBP1_1,
  NGL_GS_MIPTBP2_1,
  NGL_GS_CLAMP_1,
  NGL_GS_TEXA,
  NGL_GS_ALPHA_1,
  NGL_GS_TEST_1
};

enum
{
  NGLBM_OPAQUE,
  NGLBM_PUNCHTHROUGH,
  NGLBM_BLEND,
  NGLBM_ADDITIVE,
  NGLBM_SUBTRACTIVE,
  NGLBM_CONST_BLEND,
  NGLBM_CONST_ADDITIVE,
  NGLBM_CONST_SUBTRACTIVE,
  NGLBM_PUNCHTHROUGH_NO_ZTEST,
  NGLBM_DESTALPHA_ADDITIVE,
  NGLBM_MAX_BLEND_MODES
};

enum
{
  NGLMAP_CLAMP_U = 0x00000010,
  NGLMAP_CLAMP_V = 0x00000020
};

#define SCE_GS_SET_CLAMP(wms, wmt, minu, maxu, minv, maxv) \
  ((u_long)(wms) | (u_long)(wmt) << 2 | (u_long)(minu) << 4 | \
   (u_long)(maxu) << 14 | (u_long)(minv) << 24 | (u_long)(maxv) << 34)
#define SCE_GS_SET_PRMODE(iip, tme, fge, abe, aa1, fst, ctxt, fix) \
  ((u_long)(iip) << 3 | (u_long)(tme) << 4 | (u_long)(fge) << 5 | \
   (u_long)(abe) << 6 | (u_long)(aa1) << 7 | (u_long)(fst) << 8 | \
   (u_long)(ctxt) << 9 | (u_long)(fix) << 10)
#define GS_TEST_ZTST_M (3ULL << 17)

extern u_int nglGifRegCount;
extern u_char nglGifRegIdx[128];
extern u_long nglGifRegVal[128];
extern u_int nglGSRegIdx[];
extern const u_long nglGSBlendModes[NGLBM_MAX_BLEND_MODES][2];
extern nglScene* nglCurScene;

void nglVif1AddSetTexture( nglTexture* Tex, u_int Flags, float MipRatio );

inline void nglVif1AddGSReg( nglGSRegType Reg, u_long Val )
{
  nglGifRegIdx[nglGifRegCount] = nglGSRegIdx[Reg];
  nglGifRegVal[nglGifRegCount] = Val;
  nglGifRegCount++;
}

inline void nglVif1AddSetBlendModeCheckZTest( int Mode, int Fix = 0, bool ForceZ = false)
{
  nglVif1AddGSReg( NGL_GS_ALPHA_1, nglGSBlendModes[Mode][0] | (u_long)Fix << 32 );
  if (nglCurScene->ZTestEnable)
    nglVif1AddGSReg( NGL_GS_TEST_1,  ForceZ ? nglGSBlendModes[NGLBM_OPAQUE][1] : nglGSBlendModes[Mode][1] );
  else
    nglVif1AddGSReg( NGL_GS_TEST_1, (ForceZ ? nglGSBlendModes[NGLBM_OPAQUE][1] : nglGSBlendModes[Mode][1]) & ~GS_TEST_ZTST_M | (1<<17) );
}

void nglVif1AddQuadMaterial( nglQuad* Quad )
{
  if ( Quad->Tex )
    nglVif1AddSetTexture( Quad->Tex, Quad->MapFlags, 0.0f );
  nglVif1AddSetBlendModeCheckZTest( Quad->BlendMode, Quad->BlendModeConstant );
  nglVif1AddGSReg( NGL_GS_CLAMP_1, 
	  SCE_GS_SET_CLAMP( ( Quad->MapFlags & NGLMAP_CLAMP_U ) != 0, ( Quad->MapFlags & NGLMAP_CLAMP_V ) != 0, 0, 0, 0, 0 ) );
  nglVif1AddGSReg( NGL_GS_PRMODE, SCE_GS_SET_PRMODE( 1, Quad->Tex != 0, 0, Quad->BlendMode != NGLBM_OPAQUE, 0, 0, 0, 0 ) );
}
